#include "../src/saturn/game_library.hpp"
#include <cassert>
#include <iostream>
#include <cstdio>
using namespace shining_saturn;
int main(){GameLibrary l;assert(!l.add(GameEntry{}));assert(l.add(GameEntry{"Panzer Dragoon","panzer.cue","panzer.png","Japan","Sega","Action",1995,false,false,false}));assert(l.add(GameEntry{"Sonic 3D Blast","sonic.cue","sonic.png","USA","Sega","Platform",1996,true,true,false}));assert(l.add(GameEntry{"Virtua Fighter 2","vf2.cue","","Japan","Sega","Fighting",1995,false,false,true}));assert(l.set_favorite("panzer.cue",true));assert(l.add(GameEntry{"updated Panzer","panzer.cue","panzer.png","Japan","Sega","Action",1995,false,false,false}));assert(l.all().size()==3);assert(l.all()[0].favorite || l.all()[1].favorite || l.all()[2].favorite);GameFilter f;f.text="sonic";l.filter(f);assert(l.visible().size()==1);f=GameFilter{};f.genre="fighting";l.filter(f);assert(l.visible().size()==1);f=GameFilter{};f.save_filter=1;l.filter(f);assert(l.visible().size()==2);f=GameFilter{};f.save_filter=2;l.filter(f);assert(l.visible().size()==1);assert(l.set_favorite("panzer.cue",true));f=GameFilter{};f.favorite_filter=1;l.filter(f);assert(l.visible().size()==2);f=GameFilter{};f.favorite_filter=2;l.filter(f);assert(l.visible().size()==1 && l.visible()[0].path=="vf2.cue");assert(l.save_favorites("test-favorites.dat"));assert(l.set_favorite("panzer.cue",false));assert(l.load_favorites("test-favorites.dat"));bool panzer=false,sonic=false,vf2=false;for(const auto& g:l.all()){if(g.path=="panzer.cue")panzer=g.favorite;if(g.path=="sonic.cue")sonic=g.favorite;if(g.path=="vf2.cue")vf2=g.favorite;}assert(panzer&&!sonic&&!vf2);std::remove("test-favorites.dat");f=GameFilter{};l.filter(f,SortMode::YearDescending);assert(l.visible()[0].year==1996);assert(l.paths().covers=="Hdd1:\\ShiningSaturn360\\Covers");std::cout<<"GameLibrary tests passed\\n";}